[pkg/controller/replicaset/replica_set.go] In my mind, and what I wrote above I think this entire piece should look like this:
```golang
if batchPrecondition != nil {
	if err := batchPrecondition(successes); err != nil {
		return successes, err
	}
}
```

[pkg/registry/rbac/rolebinding/declarative_validation_test.go] This occurs because the declarative validation code doesn't execute the validations method when it sees the changed RoleRef but the handwritten validation does. This causes a mismatch between DV and HV errors.  To fix this you will have to modify the handwritten validation code flow to short-circuit in a similar way. Parity between HV and DV is mandatory.

```
            if e := validate.Immutable(ctx, op, fldPath, obj, oldObj); len(e) != 0 {
                errs = append(errs, e...)
                earlyReturn = true
            }
            if earlyReturn {
                return // do not proceed
            }
            // call the type's validation function
            errs = append(errs, Validate_RoleRef(ctx, op, fldPath, obj, oldObj)...)
```

```
func ValidateRoleBinding(roleBinding *rbac.RoleBinding , old *rbac.RoleBinding) field.ErrorList {
    allErrs := field.ErrorList{}
    allErrs = append(allErrs, validation.ValidateObjectMeta(&roleBinding.ObjectMeta, true, ValidateRBACName, field.NewPath("metadata"))...)

    if old != nil  && roleBinding.RoleRef != old.RoleRef{
        return immutable Error.
    }   
