+func ResourcesQualifyForExclusiveCPUs(res v1.ResourceRequirements) bool {
+       cpuLimit, ok := res.Limits[v1.ResourceCPU]
+       if !ok {
+               return false
+       }
+       cpuRequest, ok := res.Requests[v1.ResourceCPU]
+       if !ok {
+               return false
+       }
+       if cpuLimit.IsZero() || !cpuRequest.Equal(cpuLimit) {
+               return false
+       }
+       return cpuLimit.Value()*1000 == cpuLimit.MilliValue()
+}
```
This intentionally duplicates some QOS-related check because that part is needed to answer the question "does this resource request qualify?". I think the performance impact is negligible and dwarfed by the improved clarity and reduced coupling.

[pkg/kubelet/cm/container_manager_linux.go] Done, however I simplified the function with the new `IsContainerEquivalentQOSGuaranteed` func:
```
func ResourcesQualifyForExclusiveCPUs(container *v1.Container) bool {
	if !cmqos.IsContainerEquivalentQOSGuaranteed(container) {
		return false
	}

	cpuLimit := container.Resources.Limits[v1.ResourceCPU]
	return cpuLimit.Value()*1000 == cpuLimit.MilliValue()
}
```

