[staging/src/k8s.io/apimachinery/pkg/conversion/converter.go] would it be better or worse to register a generated self-conversion function when we add an object to a scheme in AddKnownTypeWithName, like:

```go
	...
	if t.Kind() != reflect.Ptr {
		panic("All types must be pointers to structs.")
	}

	// if the type implements DeepCopyInto(<obj>), register a self-conversion
	if m := reflect.ValueOf(obj).MethodByName("DeepCopyInto"); !m.IsZero() && m.Type().NumIn() == 1 && m.Type().NumOut() == 0 && m.Type().In(0) == reflect.TypeOf(obj) {
		if err := s.AddGeneratedConversionFunc(obj, obj, func(a, b interface{}, scope conversion.Scope) error {
			// copy a to b
			reflect.ValueOf(a).MethodByName("DeepCopyInto").Call([]reflect.Value{reflect.ValueOf(b)})
			// clear typemeta to match legacy reflective conversion
			b.(Object).GetObjectKind().SetGroupVersionKind(schema.GroupVersionKind{})
			return nil
		}); err != nil {
			panic(err)
		}
	}

	t = t.Elem()
	...
```

that would remove all reflective conversion from this method, and would let us do `SetGroupVersionKind(schema.GroupVersionKind{})` to match legacy behavior

