// UpdateRequestMetadata implements [MetadataUpdater].
func (d *Helper) UpdateRequestMetadata(
	ctx context.Context,
	claimNamespace, claimName string,
	claimUID types.UID,
	requestName string,
	devices []Device,
) error {
	if d.metadataWriter == nil {
